using Microsoft.EntityFrameworkCore;
static class FlowTests { public static async Task Run(ShiftAuditDocument data){
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
var duplicate=new ShiftAuditDocument{OpenedAt=data.OpenedAt,ClosedAt=data.ClosedAt,Events=[new(){Token=1007,At=data.OpenedAt,Action="BOOKED",Details="fallback"},new(){Token=1007,At=data.OpenedAt,Action="OrderBookedUnpaid",Details="Rs 4410"},new(){Token=1007,At=data.OpenedAt.AddMinutes(1),Action="EDITED",Details="+1 coffee"}]};Check(ShiftAuditPdf.Events(duplicate).Count==2,"Duplicate booking display");Check(duplicate.Events.Count==3,"Stored events mutated");Check(ShiftAuditPdf.ActionName("PaymentAddedAndCompleted")=="PAID + COMPLETED","Friendly action labels");
foreach(var role in new[]{"Admin","Cashier"})foreach(var path in new[]{"/api/orders","/api/orders/book"})foreach(var payNow in new[]{true,false}){var ctx=new Microsoft.AspNetCore.Http.DefaultHttpContext();ctx.Request.Method="POST";ctx.Request.Path=path;ctx.Response.Body=new MemoryStream();ctx.User=new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity(new[]{new System.Security.Claims.Claim(System.Security.Claims.ClaimTypes.Role,role)},"test"));bool ran=false;await BookingGate.Run(ctx,()=>{ran=true;return Task.CompletedTask;},()=>Task.FromResult(false));Check(!ran&&ctx.Response.StatusCode==409,$"Closed shift {role}/{path}/{payNow}");ctx=new Microsoft.AspNetCore.Http.DefaultHttpContext();ctx.Request.Method="POST";ctx.Request.Path=path;await BookingGate.Run(ctx,()=>{ran=true;return Task.CompletedTask;},()=>Task.FromResult(true));Check(ran,"Open shift booking was blocked");}
bool isOpen=true;var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var booking=new Microsoft.AspNetCore.Http.DefaultHttpContext();booking.Request.Method="POST";booking.Request.Path="/api/orders/book";var bookingTask=BookingGate.Run(booking,async()=>{entered.SetResult();await release.Task;Check(isOpen,"Shift closed during booking mutation");},()=>Task.FromResult(isOpen));await entered.Task;var closing=new Microsoft.AspNetCore.Http.DefaultHttpContext();closing.Request.Method="POST";closing.Request.Path="/api/shifts/close";var closeTask=BookingGate.Run(closing,()=>{isOpen=false;return Task.CompletedTask;},()=>Task.FromResult(isOpen));Check(isOpen,"Concurrent close bypassed booking lock");release.SetResult();await Task.WhenAll(bookingTask,closeTask);Check(!isOpen,"Close did not complete");Console.WriteLine("PASS: Admin/Cashier closed-shift guard and concurrent close serialization.");
using(var conn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:")){conn.Open();var options=new DbContextOptionsBuilder<PosDb>().UseSqlite(conn).Options;using var db=new PosDb(options);db.Database.EnsureCreated();db.Categories.Add(new Category{Name="Drinks & Shakes",Products=[new Product{Name="Cold Coffee",Variants=[new ProductVariant{Name="M",Price=300}]}]});db.SaveChanges();SuperDealsMigration.Apply(db);SuperDealsMigration.Apply(db);Check(db.Products.Count()==10,"Menu migration duplicated or lost products");Check(db.Categories.Any(x=>x.Name=="Shakes"),"Shakes rename");Check(db.Categories.Count(x=>x.Name=="Super Deals")==1,"Deal category duplicated");var variants=db.ProductVariants.Include(x=>x.Product).ToList();foreach(var deal in SuperDealsMigration.Deals)Check(variants.Single(v=>v.Product!.Name==deal.Name).Price==deal.Price,"Poster price mismatch "+deal.Name);var edited=variants.Single(v=>v.Product!.Name=="Super Deal 02");edited.Price=999;db.SaveChanges();SuperDealsMigration.Apply(db);Check(edited.Price==999,"Later menu edits overwritten");Check(variants.Single(v=>v.Product!.Name=="Cold Coffee").Price==300,"Existing price changed");}Console.WriteLine("PASS: nine poster prices, Shakes rename, idempotent seed, existing/custom prices preserved.");
var visual=new ShiftAuditDocument{ShiftNumber="SHIFT-QA-0060",OpenedAt=data.OpenedAt,ClosedAt=data.ClosedAt,Orders=[new(){Token=1007,Mode="Dine-in",Status="Completed",PaymentStatus="Paid",Total=4419,Subtotal=4910,Discount=491,Items="1x Chicken Bar.b.q (XL) @ Rs 1850 = Rs 1850; 1x Chicken Crown Crust (XL) @ Rs 2100 = Rs 2100; 3x Coca Cola (1.5 Litre) @ Rs 240 = Rs 720; 1x Pepsi (1.5 Litre) @ Rs 240 = Rs 240"}],Events=[new(){Token=1007,At=data.OpenedAt.AddMinutes(1),Action="BOOKED",Actor="Front Cashier",Role="Cashier",Details="Fallback booking record"},new(){Token=1007,At=data.OpenedAt.AddMinutes(1),Action="OrderBookedUnpaid",Actor="Front Cashier",Role="Cashier",Details="Dine-in | Rs 4410"},new(){Token=1007,At=data.OpenedAt.AddMinutes(2),Action="EDITED",Actor="Front Cashier",Role="Cashier",Details="Mixed | Added: 3x Coca Cola (1.5 Litre) @ Rs 240, 1x Pepsi (1.5 Litre) @ Rs 240 | Cancelled: 1x Cheese Fries (Regular) @ Rs 550, 1x Chocolate Ice Shake (L) @ Rs 400 | Bill Rs 4410 to Rs 4419"},new(){Token=1007,At=data.OpenedAt.AddMinutes(3),Action="PaymentAddedAndCompleted",Actor="Front Cashier",Role="Cashier",Details="Cash | Rs 4419"}]};File.WriteAllBytes("audit-test-output/shift-audit-visual.pdf",ShiftAuditPdf.Create("BT /F1 12 Tf 45 790 Td (Financial summary: existing first-page layout unchanged) Tj ET\n",visual));
}}
